def encrypt(s: str) -> str:
    if not s:
        return ""

    encrypted = []
    for char in s:
        if 'a' <= char <= 'z':
            shifted_char = chr(((ord(char) - ord('a') + 4) % 26) + ord('a'))
            encrypted.append(shifted_char)
        elif 'A' <= char <= 'Z':
            shifted_char = chr(((ord(char) - ord('A') + 4) % 26) + ord('A'))
            encrypted.append(shifted_char)
        else:
            encrypted.append(char)

    return ''.join(encrypted)
