        result.append(3)

    for i in range(2, n + 1):
        if i % 2 == 0:
            result.append(1 + i // 2)
        else:
            if i - 1 < len(result) and i - 2 < len(result) and i + 1 < len(result):
                result.append(result[i - 1] + result[i - 2] + result[i + 1])
            else:
                result.append(0)

