from typing import List
import heapq

def minPath(grid: List[List[int]], k: int) -> List[int]:
    if not grid or not grid[0]:
        return []

    n = len(grid)
    min_heap = []

    for i in range(n):
        for j in range(n):
            heapq.heappush(min_heap, (grid[i][j], i, j, [grid[i][j]]))

    while min_heap:
        current_val, x, y, path = heapq.heappop(min_heap)
        if len(path) == k:
            return path
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                heapq.heappush(min_heap, (grid[nx][ny], nx, ny, path + [grid[nx][ny]]))

    return []
