from typing import List

def poly(xs: List[float], x: float) -> float:
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: List[float]) -> float:
    if len(xs) == 0 or len(xs) % 2 != 0:
        raise ValueError("xs must have an even number of coefficients")

    if all(coeff == 0 for coeff in xs):
        raise ValueError("xs must have at least one non-zero coefficient")

    def f(x: float) -> float:
        return poly(xs, x)

    def df(x: float) -> float:
        return sum([coeff * i * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    x0 = 0.0
    for _ in range(100):
        fx = f(x0)
        if abs(fx) < 1e-6:
            return x0
        dfx = df(x0)
        if dfx == 0:
            x0 += 0.1
            continue
        x0 = x0 - fx / dfx

    return x0
